    """Check if graph has a cycle of given length using DFS"""
    # For small lengths, we can do a more targeted search
    if length == 3:
        for i in range(n):
            for j in adj[i]:
                if j > i:
                    for k in adj[j]:
                        if k > j and k in adj[i]:
                            return True
        return False

    # For general length, use DFS
    def dfs(start, current, visited, depth):
        if depth == length:
            if start in adj[current]:
                return True
            return False
        if depth > length:
            return False
        for neighbor in adj[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                if dfs(start, neighbor, visited, depth + 1):
                    return True
                visited.remove(neighbor)
        return False

    for start in range(n):
        visited = {start}
        if dfs(start, start, visited, 1):
            return True
    return False

